/* v2.2 free exploration. No tutorial prerequisites or parameter locks. */
window.TeachingUX=(()=>{'use strict';
const $=s=>document.querySelector(s),D=TeachingUXData,Z=ZeroFrictionData,C=TeachingUXCharts,M=ExperimentMath,H=HedgeMath,esc=WorkbenchUI.esc,F=(v,n=4)=>v==null?'—':Number(v).toFixed(n);
const titles={pricing:'股票价格变化，期权价格会怎样？',dividend:'股息和波动率如何影响期权价格？',iv:'已知期权价格，怎样反推出波动率？',hedge:'为什么卖出期权后，需要买入股票？'};
let id='pricing',states={},active=false,expert=false,callback,timer=null,data=null,error='';
const s=()=>states[id]||(states[id]=Z.state(id));
const details=(title,body,key='')=>`<details class="tu-details" ${key?`data-details="${key}"`:''}><summary>${title}</summary>${body}</details>`;
const facts=items=>`<dl class="tu-facts">${items.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
const figure=html=>`<div id="tuFigure" class="tu-figure">${html}</div>`;
const switches=(key,items,value)=>`<div class="tu-view">${items.map(([v,t])=>`<button data-${key}="${v}" aria-pressed="${value===v}">${t}</button>`).join('')}</div>`;
function stop(){if(timer!==null)clearInterval(timer);timer=null;const b=$('#tuPlay');if(b)b.textContent='播放';}
function clear(){stop();C.clear();}
function mount(options){callback=options.openExpert;for(const[key,parent]of [['tuModel','.model-panel'],['tuParams','.parameters'],['tuCode','.code-panel']]){const el=document.createElement('section');el.id=key;el.className='tu-only';$(parent).append(el);el.addEventListener('click',action);el.addEventListener('input',input);}
 const back=document.createElement('div');back.id='tuExpertReturn';back.innerHTML='<span>原完整工作台 · 参数独立保存</span><button id="tuReturn">返回自由探索</button>';$('#bsModules').after(back);$('#tuReturn').onclick=()=>{expert=false;open(id);};window.addEventListener('pagehide',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden)clear();});const u=new URLSearchParams(location.search);expert=u.get('experience')==='full';open(D.steps[u.get('lesson')]?u.get('lesson'):'pricing');}
function mark(){document.querySelectorAll('[data-bs-module]').forEach(b=>{b.disabled=false;b.setAttribute('aria-pressed',String(b.dataset.bsModule===id));});}
function open(module){clear();if(!D.steps[module])return;id=module;const u=new URL(location.href);u.searchParams.set('lesson',id);if(expert)u.searchParams.set('experience','full');else u.searchParams.delete('experience');history.replaceState(null,'',u);mark();if(expert){active=false;document.body.classList.remove('teaching-mode');document.body.classList.add('bs-expert');callback(id);return;}callback(null);active=true;document.body.classList.remove('bs-expert');document.body.classList.add('teaching-mode');render();}
function evaluate(){const a=s(),p=a.p;if(id==='hedge'){H.validate(p);if(a.mode==='cancel')return{current:H.option(p,p.S,p.T)};const sim=H.simulate(p);return{sim,current:H.option(p,p.S,p.T),r:sim.strategies[a.strategy].rows[Math.min(a.time,p.N)]};}if(id==='iv')return{bisection:IVMath.solve(p),newton:IVMath.solve(p,'newton')};return{now:M.bs(p)};}
function action(e){const b=e.target.closest('button');if(!b)return;const a=s();if(b.id==='tuFull'){expert=true;open(id);return;}if(b.dataset.iteration!==undefined){clear();a.time=+b.dataset.iteration;render();return;}if(b.dataset.mode){clear();a.mode=b.dataset.mode;a.line=-1;a.time=0;render();return;}if(b.dataset.method){clear();a.method=b.dataset.method;a.time=0;a.line=-1;render();return;}if(b.dataset.view){clear();a.view=b.dataset.view;render();return;}if(b.id==='tuPrevTime'||b.id==='tuNextTime'){clear();a.time+=b.id==='tuNextTime'?1:-1;render();return;}if(b.id==='tuResetTime'){clear();a.time=0;render();return;}if(b.id==='tuPlay'){if(timer!==null){stop();return;}if(!data)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){$('#tuMotion').textContent='已启用减少动态偏好，请使用上一期 / 下一期。';return;}if(a.time>=maxTime())a.time=0;timer=setInterval(()=>{if(!active||!data){stop();return;}a.time=Math.min(a.time+1,maxTime());render();if(a.time===maxTime())stop();},950);render();return;}
 if(b.dataset.codeMode){a.codeMode=b.dataset.codeMode;a.line=-1;renderCode();return;}if(b.dataset.line!==undefined){a.line=+b.dataset.line;renderCode();link();return;}if(b.id==='tuCopyStep'||b.id==='tuCopyFull'){copy(b.id==='tuCopyFull');return;}if(b.id==='tuPractice'){practice();return;}if(b.id==='tuDefaults'){clear();states[id]=Z.state(id);render();return;}if(b.id==='tuChallengeExplain'){const q=challengeData();$('#tuChallengeFeedback').textContent=(a.challenge===q.correct?'本次预测正确。':'可对照修正预测。')+q.explanation;return;}if(b.dataset.choice){a.challenge=b.dataset.choice;$('#tuChallengeFeedback').textContent='已记录预测。参数与模型始终可以自由操作；展开“为什么？”核对金融原理。';b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return;}}
function input(e){const el=e.target,a=s();if(el.id==='tuTime'){clear();a.time=+el.value;render();return;}if(el.id==='tuStrategy'){clear();a.strategy=el.value;a.line=-1;render();return;}if(el.id==='tuGreek'||el.id==='tuType'){clear();a[el.id==='tuGreek'?'greek':'type']=el.value;a.line=-1;render();return;}if(!el.dataset.key)return;clear();const k=el.dataset.key;a.p[k]=k==='type'?el.value:el.value.trim()===''?NaN:+el.value;a.time=0;a.line=-1;document.querySelectorAll('#tuParams .linked').forEach(node=>node.classList.remove('linked'));
 // A new contract starts a fresh initial hedge. Changing only S preserves the historical holding.
 if(id==='hedge'&&k!=='S'&&['K','T','r','q','sigma','type'].includes(k)){try{a.baseline={S:a.p.S,delta:H.option(a.p,a.p.S,a.p.T).delta};}catch{a.baseline={S:a.p.S,delta:null};}}
 const focus=el.id;render(false);for(const node of document.querySelectorAll(`[data-key="${k}"]`))if(node!==el)node.value=el.value;document.getElementById(focus)?.focus({preventScroll:true});}
function render(params=true){if(!active)return;C.clear();const a=s(),scroll=$('#tuBody')?.scrollTop||0,ps=$('#tuParams')?.scrollTop||0,focus=document.activeElement?.id,opened=[...document.querySelectorAll('#tuModel details[open],#tuParams details[open]')].map(d=>d.dataset.details).filter(Boolean);a.time=Math.max(0,a.time);try{data=evaluate();error='';}catch(e){data=null;error=e.message;}if(data&&id==='iv')a.time=Math.min(a.time,Math.max(0,data[a.method==='newton'?'newton':'bisection'].rows.length-1));
 $('#tuModel').innerHTML=`<h3 class="tu-question">${titles[id]}</h3><div id="tuBody"></div>`;if(params)renderParams();if(error){$('#tuBody').innerHTML=`<p class="tu-error" role="alert">${esc(error)}；旧结果与轨迹已清除。</p>`;$('#tuCode').innerHTML='<p class="tu-note">请修正参数后复制代码。</p>';return;}
 $('#tuBody').innerHTML=(id==='hedge'?hedge():id==='iv'?implied():prices())+challenge()+details('模型假设与完整工作台',`<p>欧式期权、Black–Scholes、连续股息、同一无风险借贷利率；允许卖空和分数股票，一份教学期权对应一单位标的。动态模拟采用风险中性GBM，定价与模拟波动率一致，无交易成本、离散调仓。模拟路径不是市场预测，策略不保证盈利。</p><button id="tuFull">打开原完整工作台</button><p>原工作台保留全部旧功能，参数独立保存；返回会保留本页自由探索条件。</p>`,'assumptions');
 if(id==='hedge'&&a.mode==='dynamic')C.bind($('#tuFigure'),data.sim,'B',a.strategy);renderCode();for(const key of opened)document.querySelector(`[data-details="${key}"]`)?.setAttribute('open','');$('#tuBody').scrollTop=scroll;$('#tuParams').scrollTop=ps;if(['tuTime','tuPlay','tuNextTime','tuPrevTime','tuResetTime'].includes(focus))document.getElementById(focus)?.focus({preventScroll:true});mark();}
function hedge(){const a=s(),p=a.p,v=data.current,h=v.delta,base=a.baseline.delta;const toggle=switches('mode',[['cancel','风险抵消'],['dynamic','动态调仓']],a.mode);if(a.mode==='cancel')return toggle+`<p class="zf-intro">${p.type==='C'?'卖出看涨期权后，股价上涨可能增加期权支付义务。买入适量股票，可以抵消股价小幅变化带来的一阶风险。':'卖出看跌期权后，股价下跌可能增加期权支付义务。卖空适量股票，可以抵消股价小幅变化带来的一阶风险。'}</p>`+figure(C.cancel(h))+`<div id="tuLive" aria-live="polite">${facts([['期权 Delta',F(h)],['当前所需股票',F(h)+' 单位'],['净 Delta','0.0000']])}</div><p id="tuInsight" class="tu-insight">${p.S===a.baseline.S?'股价每发生很小的变化，卖出期权与目标股票持仓的一阶价值变化大约相互抵消。':`股价从 ${F(a.baseline.S,2)} 变为 ${F(p.S,2)} 元，Delta变为 ${F(h)}；维持当前中性需要${h-base>=0?'增加':'减少'} ${F(Math.abs(h-base))} 单位股票。`}Delta中性不代表完全无风险。</p><p class="zf-holdings">初始持仓 <b id="tuInitial">${F(base)}</b> → 当前目标 <b id="tuTarget">${F(h)}</b> 单位<br>初始股价 ${F(a.baseline.S,2)} 元；原持仓未调整时净Delta ${F(base-h)}。这是目标数量重算，尚未执行交易。</p>`+
 details('为什么？',`<p>Delta是局部价格敏感度，不是上涨概率。卖出一份期权的Delta是−Δ；每单位股票的Delta是1，所以持有h=Δ可使−Δ+h=0。Put的Delta为负，因此股票对冲方向为卖空。</p><p>股价改变会改变Delta；Gamma衡量这种变化。原股票持仓不会自动改变，有限价格变动还有非线性风险。修改合约的K、T、r、q、σ或类型时，本页按当前S重建初始参照；仅修改S则保持初始持仓。</p>`,'why')+
 details('查看资金与现金账户计算',`<p>按当前条件重新建立一份教学期权的对冲：卖出期权收入 ${F(v.price,6)} 元；股票成本 hS=${F(h*p.S,6)} 元；B₀=V₀−hS=${F(v.price-h*p.S,6)} 元；初始净值 hS+B₀−V₀=0。</p><p>负现金表示借入资金，不代表已经亏损。这里是当前新建账户的资金计算；原持仓的逐期自融资账户请切换“动态调仓”。</p>`,'cash')+
 details('数学与六位计算',`<div data-formula="delta"></div><p>d₁=${F(M.bs(Z.core(p)).d1,6)}，期权Delta=${F(h,6)}；股票目标=${F(h,6)}，净Delta=${F(-h+h,6)}。剩余期限与其他参数固定，仅改变S。</p>`,'math');
 const sim=data.sim,r=data.r;return toggle+`<p class="zf-intro">同一路径上，按约定时点调整股票；账户自动计入利息、股息和调仓现金流。这是教学模拟。</p>`+switches('view',[['path','股价与调仓'],['performance','Hedging Performance']],a.view)+`<label class="zf-strategy">观察策略<select id="tuStrategy">${[['none','不对冲'],['static','静态Delta'],['dynamic','动态Delta']].map(([v,t])=>`<option value="${v}" ${a.strategy===v?'selected':''}>${t}</option>`).join('')}</select></label>${a.view==='performance'?'<p class="zf-legend">棕色虚线：不对冲 · 蓝色虚线：静态 · 绿色实线：动态</p>':''}`+figure(C.dynamic(sim,a.time,'C',a.view,a.strategy))+'<div id="tuTip" hidden role="status"></div>'+controls(p.N)+facts([['第 '+a.time+' 期 · 股价',F(r.S,2)],['实际持仓 / 本期交易',F(r.holding)+' / '+F(r.quantity)],['当前净值 / 最终误差',F(r.net)+' / '+F(sim.strategies[a.strategy].error)]])+`<p id="tuInsight" class="tu-insight">${r.i===0?'初始股票与现金共同抵消期权负债，净值约为0。':r.i===p.N?'已到期：期权使用真实支付函数，股票清算后现金等于终点净值。':r.rebalance?`本期重新计算Delta，交易 ${F(r.quantity)} 单位股票；${r.quantity>=0?'买入支付现金':'卖出收回现金'}。`:'本期不是该策略的调仓时点，继续持有原数量。'}更频繁调仓不保证每条路径误差都更小。</p>`+
 details('查看账户与三策略结果',facts([['期权理论价 / 到期支付',F(r.price,6)],['期权Delta',F(r.delta,6)],['现金账户',F(r.cash,6)],['调仓前现金',F(r.cashBefore,6)],['利息 / 股息',F(r.interest,6)+' / '+F(r.dividend,6)],['交易现金流',F(r.tradeCash,6)]])+`<table class="tu-table"><tr><th>同一路径</th><th>当前净值</th><th>最终误差</th></tr>${Object.entries(sim.strategies).map(([k,v])=>`<tr><th>${{none:'不对冲',static:'静态',dynamic:'动态'}[k]}</th><td>${F(v.rows[a.time].net,6)}</td><td>${F(v.error,6)}</td></tr>`).join('')}</table><p>现金 Bᵢ=Bᵢ₋₁exp(rΔt)+股息−交易量×Sᵢ。股息以期初持仓×期初股价×q×Δt作左端点矩形近似，期末入账；空头股息为支出。净值=hS+B−V。负现金是借款；到期不再调仓，期权Delta留空。</p>`,'account')+details('为什么仍有对冲误差？','<p>连续时间理论使用连续调仓；这里仅在有限时点交易。路径的非线性变化与股息离散近似都会留下误差。三策略使用同一期权、初始权利金、利率、股息和股价路径，动态对冲未必在每条路径上最好。</p>','why');}
function prices(){const a=s(),p=a.p,v=data.now,pay=id==='pricing'&&a.mode==='payoff',greek=id==='dividend'&&a.mode==='greek';const toggle=id==='pricing'?switches('mode',[['price','理论价格'],['payoff','到期支付']],a.mode):switches('mode',[['price','价格变化'],['greek','查看Greeks']],a.mode);let chart=greek?C.price(p,a.type,a.greek):C.prices(p,{payoff:pay,dividend:id==='dividend'});const key={delta:a.type==='P'?'deltaP':'deltaC',gamma:'gamma',vega:'vega',theta:a.type==='P'?'thetaP':'thetaC'}[a.greek];return toggle+`<p class="zf-intro">${pay?'到期时，买方有利才行权；支付尚未减去权利金，不能当作投资利润。':id==='pricing'?'直接改变股价，比较两种买卖权利的理论价格。蓝色为Call，棕色为Put。':greek?'一次观察一种局部敏感度，其他条件保持固定。':'拖动股息q或波动率σ，立即观察两类理论价格。蓝色Call，棕色Put。'}</p>`+chartControls()+figure(chart)+facts(greek?[[a.greek+' 当前值',F(v[key])]]:[['Call '+(pay?'到期支付':'理论价格'),F(pay?Math.max(p.S-p.K,0):v.C)],['Put '+(pay?'到期支付':'理论价格'),F(pay?Math.max(p.K-p.S,0):v.P)]])+`<p id="tuInsight" class="tu-insight">${pay?'此视图把S当作情景到期股价；即使显示同样的数字，到期支付与尚未到期的模型价格也不同。':greek?{delta:'Delta是股价局部变化时的价格敏感度，不是上涨概率。',gamma:'Gamma衡量Delta随股价变化的速度。',vega:'Vega显示波动率每增加1个百分点时的局部价格变化；原始导数为此值的100倍。',theta:'Theta按每天显示：−期限导数÷365；在不同条件下未必为负。'}[a.greek]:id==='pricing'?`当前股价 ${F(p.S,2)} 元。其他条件固定时，提高股价会令Call非减、Put非增；曲线上的点实时对应当前条件。`:`当前q=${F(p.q*100,2)}%、σ=${F(p.sigma*100,2)}%。其他条件固定，提高q令Call非增、Put非减；提高波动率通常提高两类欧式期权价格。`}</p>`+
 details('为什么？',id==='pricing'?'<p>Call允许按执行价买入，股价更高时这项权利通常更值钱；Put允许按执行价卖出，方向相反。尚未到期还有未来机会，因此当前价格要考虑时间、波动率和贴现。到期支付与扣除成本后的利润不同。</p>':'<p>股息降低Se⁻ᑫᵀ这一调整后的标的项，所以Call下降、Put上升。波动更大增加极端有利结果的机会，买方仍可放弃不利行权。边界下价格变化可不严格；Greeks是局部近似。</p>','why')+
 details('数学、贴现与精确结果',`<div data-formula="price"></div><p>d₁=${F(v.d1,6)}，d₂=${F(v.d2,6)}；Φ为标准正态分布函数。股票项贴现Se⁻ᑫᵀ，执行价贴现Ke⁻ʳᵀ。</p><p>Call=${F(v.C,6)}，Put=${F(v.P,6)}；平价C−P=Se⁻ᑫᵀ−Ke⁻ʳᵀ=${F(v.A-v.D,6)}。T=0或σ=0调用原引擎边界分支，折点Greeks可能未定义。</p>`,'math');}
function chartControls(){if(id!=='dividend'||s().mode!=='greek')return '';return `<div class="zf-greek"><label>指标<select id="tuGreek">${['delta','gamma','vega','theta'].map(k=>`<option value="${k}" ${s().greek===k?'selected':''}>${k}</option>`).join('')}</select></label><label>期权<select id="tuType"><option value="C" ${s().type==='C'?'selected':''}>Call</option><option value="P" ${s().type==='P'?'selected':''}>Put</option></select></label></div>`;}
function implied(){const a=s(),p=a.p;let html=switches('method',[['bisection','二分法'],['newton','牛顿法'],['compare','算法比较']],a.method)+'<p class="zf-intro">寻找一个波动率，让BS理论价格接近给定的假设报价。这不是实际市场成交价，也不是已知的未来波动率。</p>';const res=data[a.method==='newton'?'newton':'bisection'],row=res.rows[a.time];html+=figure(C.iteration(p,res,a.time));if(a.method==='compare')return html+`<table class="tu-table"><tr><th>纯算法</th><th>IV估计 / 步数</th><th>状态与误差</th></tr>${Object.entries(data).map(([k,r])=>`<tr><th>${k}</th><td>${F(r.sigma==null?null:r.sigma*100)}% / ${r.iterations}</td><td>${esc(IVMath.reasons[r.status])}；${r.error==null?'—':r.error.toExponential(3)}</td></tr>`).join('')}</table><p class="tu-insight">Newton依赖初值和足够Vega，可能失败；两种算法均未使用隐藏回退。上图保留二分轨迹。</p>`;
 const failures=!res.converged?`<p class="tu-error" role="alert">算法终止：${esc(IVMath.reasons[res.status])}；${res.sigma==null?'无有限估计':'未将估计冒充收敛结果'}。</p>`:'';html+=failures+controls(Math.max(0,res.rows.length-1))+facts([['假设报价',F(p.target,6)],['当前σ估计',row?F(row.sigma*100)+'%':res.sigma===0?'0%（边界）':'—'],['本步理论价格',row?F(row.theoreticalPrice,6):'—']])+`<p id="tuInsight" class="tu-insight">${row?(a.method==='bisection'?`当前区间 [${F(row.a*100,3)}%, ${F(row.b*100,3)}%]；用价格残差决定下一半区间。`:`切线使用对小数波动率的原始Vega ${F(row.vega,6)}；下一σ ${F(row.nextSigma==null?null:row.nextSigma*100)}%。`):esc(IVMath.reasons[res.status])}</p>`;
 return html+details('为什么？','<p>BS价格在常规条件下随波动率增加。二分法需要包围解的区间并逐次减半；Newton利用斜率外推，快慢与初值、Vega有关。报价处于无套利下界可对应σ=0，上界通常只有无限波动率极限；T=0不能反推出唯一IV。</p>','why')+details('迭代日志、公式与停止诊断',`<div data-formula="iv"></div><p>停止状态：${esc(IVMath.reasons[res.status])}；扩展 ${res.expansions} 次；容差 ${p.tol} 元；最大 ${p.maxIter} 步。价格上下界 [${F(res.lower,6)}, ${F(res.upper,6)}]。最终误差 ${res.error==null?'—':res.error.toExponential(6)}。</p><label>选择任意迭代<input id="tuTime" type="range" min="0" max="${Math.max(0,res.rows.length-1)}" value="${a.time}"></label><table class="tu-table"><tr><th>n</th><th>σ</th><th>价格残差</th><th>下一σ / 区间</th></tr>${res.rows.map((r,i)=>`<tr ${i===a.time?'class="selected"':''}><td><button data-iteration="${i}">${i+1}</button></td><td>${F(r.sigma,6)}</td><td>${r.signedError.toExponential(4)}</td><td>${a.method==='newton'?F(r.nextSigma,6):F(r.nextA,6)+' / '+F(r.nextB,6)}</td></tr>`).join('')}</table>`,'iterations');}
function controls(n){return `<div class="tu-play"><button id="tuPrevTime" ${s().time===0?'disabled':''}>${id==='iv'?'上次迭代':'上一期'}</button><span>${s().time} / ${n}</span><button id="tuNextTime" ${s().time>=n?'disabled':''}>${id==='iv'?'下一次迭代':'下一期'}</button><button id="tuPlay" ${n===0?'disabled':''}>${timer!==null?'暂停':id==='iv'?'开始求解':'播放'}</button><button id="tuResetTime">重置</button></div><p id="tuMotion" role="status"></p>`;}
function maxTime(){return id==='hedge'?s().p.N:id==='iv'?Math.max(0,data[s().method==='newton'?'newton':'bisection'].rows.length-1):0;}
function challengeData(){return {
 hedge:{question:'默认Call案例，S从100涨到105元且剩余期限不变，原持仓还能保持Delta中性吗？',choices:[['same','仍能，原数量不用变'],['change','不能，需重新计算数量']],correct:'change',explanation:'同源引擎：旧Delta约0.6368，新Delta约0.7237，需增加约0.0869单位；原股票不会自动调整。'},
 pricing:{question:'固定其他条件，提高股价，Call与Put价格怎样变化？',choices:[['upDown','Call非减、Put非增'],['downUp','Call非增、Put非减']],correct:'upDown',explanation:'Call是按执行价买入的权利，Put是按执行价卖出的权利，二者对股价的局部敏感度方向相反。'},
 dividend:{question:'固定其他条件，增加连续股息q，Call与Put价格怎样变化？',choices:[['downUp','Call非增、Put非减'],['upDown','Call非减、Put非增']],correct:'downUp',explanation:'q提高使Se⁻ᑫᵀ下降。另可固定q，将σ提高10个百分点比较：两类欧式期权价格通常提高，边界可能不严格变化。'},
 iv:{question:'默认平价案例，Newton初值30%会比二分法迭代更少吗？',choices:[['faster','默认案例是，但不能推广到所有初值'],['always','任何初值都会更快']],correct:'faster',explanation:'默认同源计算：二分28步，Newton4步。Newton依赖初值与足够Vega，其他条件下可能越界或失败；纯算法没有隐藏回退。'}
}[id];}
function challenge(){const q=challengeData();return details('课堂挑战（可选）',`<p>${q.question}</p><div class="tu-choices">${q.choices.map(([v,t])=>`<button data-choice="${v}" aria-pressed="${s().challenge===v}">${t}</button>`).join('')}</div><button id="tuChallengeExplain">查看挑战解释</button><p id="tuChallengeFeedback">可以先预测，再自由修改参数验证；模型始终可用。${id==='hedge'?'另一个卖方情景：默认Call到期股价120元，支付义务是多少？初始权利金减到期支付（忽略利息）又是多少？这与完整账户终值不同。':''}</p>`,'challenge');}
function renderParams(){const a=s(),p=a.p,desc={S:['股票价格 S（元）',.01,1e5],K:['执行价格 K（元）',.01,1e5],T:['期限 T（年）',id==='hedge'?.0001:0,10],r:['利率 r（小数）',-.1,.3],q:['股息 q（小数）',0,1],sigma:['波动率 σ（小数）',0,2],N:['路径步数 N',1,504],interval:['每隔几期调仓',1,504],seed:['随机种子',0,2147483646],target:['假设期权报价（元）',0,1e5],initial:['Newton初值（小数）',1e-8,1e6],tol:['价格容差（元）',1e-12,.01],maxIter:['最大迭代次数',1,200]};let primary,adv;
 if(id==='hedge'&&a.mode==='cancel'){primary=['S','K','type','sigma'];adv=['T','r','q'];}else if(id==='hedge'){primary=['interval','N','seed'];adv=['S','K','type','sigma','T','r','q'];}else if(id==='pricing'){primary=['S','K','T','r','sigma'];adv=['q'];}else if(id==='dividend'){primary=['q','sigma'];adv=['S','K','T','r'];}else{primary=['target','type',...(a.method==='newton'?['initial']:[])];adv=['S','K','T','r','q',...(a.method==='newton'?[]:['initial']),'tol','maxIter'];}
 const field=k=>k==='type'?`<label data-tu-field="type">期权类型<select id="tu-p-type" data-key="type"><option value="C" ${p.type==='C'?'selected':''}>Call 看涨</option><option value="P" ${p.type==='P'?'selected':''}>Put 看跌</option></select></label>`:`<label data-tu-field="${k}">${desc[k][0]}<input id="tu-p-${k}" data-key="${k}" type="number" min="${desc[k][1]}" max="${desc[k][2]}" step="${['N','interval','seed','maxIter'].includes(k)?1:'any'}" value="${Number.isFinite(p[k])?p[k]:''}"></label>${(id==='hedge'&&a.mode==='cancel'&&k==='S')||id==='dividend'&&['q','sigma'].includes(k)?`<input id="tu-slider-${k}" aria-label="拖动${desc[k][0]}" data-key="${k}" type="range" min="${k==='S'?Math.max(.01,Math.min(p.S*.8,a.baseline.S*.8)):0}" max="${k==='S'?Math.min(1e5,Math.max(p.S*1.2,a.baseline.S*1.2)):k==='q'?Math.max(.1,p.q):Math.max(.6,p.sigma)}" step="${k==='S'?.1:.001}" value="${p[k]}">`:''}`;
 $('#tuParams').innerHTML=`<h3>${id==='hedge'&&a.mode==='dynamic'?'路径与调仓设置':'核心参数'}</h3>${primary.map(field).join('')}${details('更多参数',adv.map(field).join(''),'advanced')}<button id="tuDefaults">恢复默认条件</button><p class="tu-note">${id==='hedge'&&a.mode==='dynamic'?'修改条件立即重算并回到第0期；只改调仓间隔保持同一路径。':'参数改变立即更新，无需提交。数值按小数输入：0.2=20%。'}</p>`;}
function renderCode(){if(!active||!data)return;const a=s(),full=a.codeMode==='full';let lines=full?D.formatR(Z.script(id,a,true),TeachingCode.wrap).split('\n'):Z.snippet(id,a);if(!full&&id==='hedge'&&a.mode==='cancel'&&(a.p.sigma===0||a.p.T===0))lines=['value <- bs(S,K,T,r,sigma,q)',`delta <- value["${a.p.type==='P'?'deltaP':'deltaC'}"]`,'shares <- delta','net_delta <- -delta+shares'];const sc=$('#tuCodeLines')?.scrollTop||0,mathOpen=$('[data-details=code-math]')?.open;
 $('#tuCode').innerHTML=`<div class="tu-codebar"><button data-code-mode="point" aria-pressed="${!full}">基础代码</button><button data-code-mode="full" aria-pressed="${full}">完整代码</button></div><p class="tu-code-notice">${full?'完整独立脚本 · 网页不运行R':'核心片段；复制基础脚本会补齐参数、函数与边界处理'}</p><div class="tu-copybar"><button id="tuCopyStep">复制基础脚本</button><button id="tuCopyFull">复制完整脚本</button><button id="tuPractice">RStudio实践</button></div><div class="tu-code-regions"><div id="tuCodeLines" tabindex="0">${lines.map((l,i)=>`<button class="code-line ${a.line===i?'selected':''}" data-line="${i}" aria-pressed="${a.line===i}"><span class="num">${i+1}</span><code>${WorkbenchUI.colorCode(l)||' '}</code></button>`).join('')}</div><section id="tuCodeExplain"><h3>参数 → 计算 → 金融含义</h3><p>${codeExplanation()}</p>${details('数学与当前代入','<div id="tuFormula"></div><p>'+substitution()+'</p>','code-math')}</section></div><p id="tuCopyStatus" role="status"></p>`;$('#tuCodeLines').scrollTop=sc;if(mathOpen)$('[data-details=code-math]').open=true;const formula=id==='hedge'?'h=\\Delta,\\quad \\Pi=hS+B-V':id==='iv'?'f(\\sigma)=BS(\\sigma)-P_{quote}':'C=Se^{-qT}\\Phi(d_1)-Ke^{-rT}\\Phi(d_2)';katex.render(formula,$('#tuFormula'),{throwOnError:false});document.querySelectorAll('[data-formula]').forEach(el=>katex.render(el.dataset.formula==='delta'?'\\Delta_C=e^{-qT}\\Phi(d_1),\\quad \\Delta_P=e^{-qT}(\\Phi(d_1)-1)':el.dataset.formula==='iv'?'\\sigma_{n+1}=\\sigma_n-f(\\sigma_n)/Vega_{raw}':formula,el,{throwOnError:false}));}
function codeExplanation(){if(id==='hedge'&&s().mode==='cancel')return['d₁组合股价、执行价、期限与波动率；Delta调用连续股息公式。','Delta是局部价格敏感度；Call非负，Put非正。','目标股票数量等于期权Delta；负数代表卖空股票。','卖方Delta取负，目标股票Delta与之抵消；这是当前目标关系。'][Math.min(3,Math.max(0,s().line))];if(id==='hedge')return'只在调仓时点交易，现金同时扣除购股支出并计入利息与股息；净值减去期权负债。';if(id==='iv')return'当前图与迭代使用同一求根记录；Vega使用对小数波动率的导数，失败不会改标成功。';return'调用同源Black–Scholes函数；Call与Put为理论价格，到期支付另行展示。';}
function substitution(){if(id==='hedge')return s().mode==='cancel'?`Delta=${F(data.current.delta,6)}，初始股票=${F(s().baseline.delta,6)}，当前目标=${F(data.current.delta,6)}。`:`第${s().time}期：持仓=${F(data.r.holding,6)}，现金=${F(data.r.cash,6)}，净值=${F(data.r.net,6)}。`;if(id==='iv'){const row=data[s().method==='newton'?'newton':'bisection'].rows[s().time];return row?`σ=${F(row.sigma,6)}；价格=${F(row.theoreticalPrice,6)}；误差=${row.signedError.toExponential(6)}。`:'本边界没有有效迭代轨迹。';}return`Call=${F(data.now.C,6)}，Put=${F(data.now.P,6)}；q=${s().p.q}，σ=${s().p.sigma}。`;}
function link(){const a=s();$('#tuFigure')?.removeAttribute('data-code-focus');if(id==='hedge'&&a.mode==='cancel'){const k=a.line===2?'shares':a.line===3?'net':'delta';$('#tuFigure')?.setAttribute('data-code-focus',k);}else $('#tuFigure')?.classList.add('tu-linked');document.querySelectorAll('[data-tu-field]').forEach(el=>el.classList.toggle('linked',id==='hedge'&&a.line<2&&['S','K','T','r','q','sigma'].includes(el.dataset.tuField)));}
async function copy(full){if(!data)return;const code=D.formatR(Z.script(id,s(),full),TeachingCode.wrap);try{await navigator.clipboard.writeText(code);$('#tuCopyStatus').textContent='已复制可独立运行的R脚本（包含当前参数和必要上下文）。';}catch{const url=URL.createObjectURL(new Blob([code],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=id+(full?'-full':'-basic')+'.R';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#tuCopyStatus').textContent='已下载独立R脚本。';}}
function practice(){$('#infoTitle').textContent='RStudio 独立实践';$('#infoBody').textContent='新建R Script，复制基础或完整脚本并整段运行；网页本身不执行R。\n当前可核对结果：'+substitution()+'\n'+(id==='hedge'?'完整模拟默认seed2027、N60、interval1时三策略终值约为10.968223、7.714696、−0.179013元。保持seed和N不变，仅修改interval，比较同路径误差并解释为何未必单调改善。':id==='iv'?'默认假设报价10.450583572185565应反解约20%。修改Newton初值，观察是否收敛及停止原因。':'只修改一个参数，比较两类价格，再解释变化方向。');ModalUI.open($('#infoDialog'));}
return{mount,open,full(){expert=true;open(id);}};
})();
